#include <omp.h>
#include <cstddef>
#include <vector>

int maxDegree(std::vector<int> const& A, size_t N) {
    if (N == 0) {
        return 0;
    }

    // Validate that A contains at least an NxN matrix without risking overflow in N*N.
    if (A.size() / N < N) {
        return 0;
    }

    int max_degree = 0;

    #pragma omp parallel for default(none) shared(A, N) reduction(max:max_degree) schedule(static)
    for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
        const size_t row_offset = static_cast<size_t>(i) * N;
        int degree = 0;

        #pragma omp simd reduction(+:degree)
        for (std::ptrdiff_t j = 0; j < static_cast<std::ptrdiff_t>(N); ++j) {
            degree += A[row_offset + static_cast<size_t>(j)];
        }

        if (degree > max_degree) {
            max_degree = degree;
        }
    }

    return max_degree;
}
